const httpItem = $('جلب بيانات النظام (Supabase)').first().json;
const row = Array.isArray(httpItem) ? httpItem[0] : httpItem;
const data = row && row.data ? row.data : row;
const staffEmails = $('إعدادات المستلمين (عدّل هنا)').first().json.staffEmails;

const today = new Date().toISOString().slice(0, 10);

const dueTasks = (data.tasks || []).filter(t => t.due === today && t.status !== 'مكتملة');
const overdueTasks = (data.tasks || []).filter(t => t.due && t.due < today && t.status !== 'مكتملة');
const followUps = (data.counselCases || []).filter(c => c.followDate === today && c.status !== 'مغلقة');

const teacherAbsencesToday = (data.teacherAbsences || []).filter(a => a.date === today);
const uncovered = teacherAbsencesToday.map(a => {
  const covered = Object.values(a.covers || {}).filter(Boolean).length;
  const net = Math.max(0, (a.missing || 0) - covered);
  return { empName: a.empName, type: a.type, missing: a.missing || 0, covered, net };
}).filter(a => a.net > 0);

const section = (title, items, cols) => {
  if (!items.length) return `<h3>${title}</h3><p>لا يوجد</p>`;
  return `<h3>${title} (${items.length})</h3><ul>${items.map(cols).join('')}</ul>`;
};

const html = `
<h2>تذكيرات اليوم - ${today} - ${data.settings ? data.settings.schoolName : ''}</h2>
${section('مهام مستحقة اليوم', dueTasks, t => `<li>${t.title} — مكلَّف: ${t.assignee}</li>`)}
${section('مهام متأخرة', overdueTasks, t => `<li>${t.title} — مكلَّف: ${t.assignee} — الاستحقاق: ${t.due}</li>`)}
${section('متابعات حالات إرشادية اليوم', followUps, c => `<li>الطالب: ${c.student}</li>`)}
${section('حصص شاغرة تحتاج سداً اليوم', uncovered, a => `<li>${a.empName} (${a.type}) — متبقٍّ بلا تغطية: ${a.net} حصة</li>`)}
`;

return [{ json: { html, today, staffEmails, schoolName: data.settings ? data.settings.schoolName : '' } }];
